function buildHighSchoolShortstopExecution(match, situation, choice, sample) {
  const handoff = match.groundBallInPlayState;
  if (!Number.isFinite(sample) || sample < 0 || sample >= 1) throw new Error("Invalid SS execution sample");
  assertHighSchoolDetailedResponsibility(match, handoff.physicalTruth, "SS", "player");
  if (situation.playerPosition !== "游擊手" || !handoff.supported) throw new Error("Invalid SS production context");
  const secureResolution = resolveHighSchoolCanonicalSecure(match, handoff, sample);
  const input = getHighSchoolControlledDecisionInput(match, { ...handoff, secureResolution });
  const opportunity = DefensiveDecisionThrowFoundation.buildDecisionOpportunity(input);
  const controlled = opportunity.status === "controlledDecision";
  const selection = controlled ? DefensiveDecisionThrowFoundation.selectDefensiveRoute(opportunity, choice.routeId, input) : null;
  const thrown = selection ? DefensiveDecisionThrowFoundation.resolveThrow({ input, opportunity, selection,
    capabilities: { defenderId: "player", arm: situation.playerCapabilities.arm, throwing: situation.playerCapabilities.throwing },
    transferState: secureResolution.secureQuality === "bobbleButControlled" ? "delayed" : "ready" }) : null;
  const swing = (sample - 0.5) * 4;
  const receiver = selection?.route.receiverPosition
    ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], selection.route.receiverPosition) : null;
  const receiverCapabilities = receiver ? getDefensiveSimulationCapability(receiver, receiver.position, match) : {};
  const receiverReady = Boolean(receiver && (Number(receiverCapabilities.fielding) || 5) + swing >= 3.2);
  input.receiverState = { receiverId: receiver?.id || null, ready: receiverReady, atBase: true, tagAvailable: receiverReady, tagDelay: 1 };
  const decisionThrowState = { opportunity, preControlIntent: choice.routeId, selection, activeSelection: selection, throwResolution: thrown };
  // Failed acquisition has no controlled decision or throw. Preserve the existing
  // Foundation's no-contest diagnostic so lifecycle recovery still has an owner.
  let runnerThrowTiming = selection ? null : DefensiveRunnerThrowSettlementFoundation.projectExistingTiming({
    stage: decisionThrowState, runnerState: null, windowState: "expired", receiverFact: "unavailable" });
  let firstLegSettlement = null;
  if (selection) {
    const timingArgs = { input, opportunity, selection, throwResolution: thrown,
      runnerState: input.runnerPhysicalStates.find(r => r.runnerId === selection.route.targetRunnerId),
      receiverState: input.receiverState, resolveThirdOut: resolveHighSchoolThirdOutIntegrity };
    runnerThrowTiming = DefensiveRunnerThrowSettlementFoundation.resolveTiming(timingArgs);
    firstLegSettlement = DefensiveRunnerThrowSettlementFoundation.deriveSettlement({ ...timingArgs, timing: runnerThrowTiming });
  }
  const firstOut = firstLegSettlement?.outRecorded === true;
  const continuationWindow = handoff.timingWindows.relayToFirstWindow.state;
  const isDoublePlay = choice.infieldRoute === "doublePlay";
  // Relay completion reuses the established 2B/SS receive-turn-deliver model.
  const relay = resolveInfieldRelayToFirst(situation, firstOut, sample, continuationWindow, receiverCapabilities);
  const secondOut = isDoublePlay && firstOut && situation.outs < 2 && relay.secondOutAvailable;
  const retirements = firstOut ? [{ runnerId: selection.route.targetRunnerId, targetBase: selection.route.targetBase,
    outType: firstLegSettlement.playType === "batterRunner" ? "batterRunnerBeforeFirst" : firstLegSettlement.playType === "force" ? "force" : "nonForceTag", sequence: 1 }] : [];
  if (secondOut) retirements.push({ runnerId: situation.batterId, targetBase: "first", outType: "batterRunnerBeforeFirst", sequence: 2 });
  // Complete all committed actors after the first-leg contest. The existing force
  // owner accounts for in-transit runners, collisions, and force removal after outs.
  const runnerSettlement = ForceAdvancement.settleForceAdvancement({ forceChain: situation.forceChain,
    movementIntents: situation.movementIntents, retirements });
  const error = (secureResolution.attemptAvailable && !secureResolution.secured) || thrown?.throwQuality === "offline";
  const resultCode = secondOut ? "twoOuts" : firstOut ? "oneOut" : error ? "error" : "zeroOuts";
  const detailedResult = secondOut ? "completedDoublePlay" : firstOut ? (isDoublePlay ? "secondStageExpired" : "cleanOut")
    : error ? (secureResolution.secured ? "inaccurateThrow" : "fieldingError") : !secureResolution.secured ? "lateFielding"
      : choice.infieldRoute === "controlledNoThrow" ? "controlledNoThrow" : "lateThrow";
  const primaryCause = !secureResolution.secured ? "playerFieldingControl" : thrown?.throwQuality === "offline" ? "playerFirstThrow"
    : !receiverReady && selection?.route.action !== "holdBall"
      ? selection?.route.receiverPosition === "1B" ? "teammateFirstBaseReceive" : selection?.route.receiverPosition === "C" ? "teammateHomeReceive" : "teammatePivot"
      : isDoublePlay && firstOut && !relay.turn && situation.batterSpeed < 8 && continuationWindow !== "narrow" ? "teammatePivot"
        : isDoublePlay && firstOut && relay.turn && !relay.firstBaseReceive ? "teammateFirstBaseReceive"
          : choice.infieldRoute === "controlledNoThrow" ? "balancedExecution"
            : !firstOut || (isDoublePlay && !secondOut) ? "timingWindow" : "balancedExecution";
  const resolution = attachDefensiveOutcomeExplanation(situation, choice, {
    familyId: "infield", route: choice.infieldRoute, routeId: choice.routeId, initialRoute: choice.routeId, activeRoute: choice.routeId,
    playerRole: "initiator", responsibility: situation.responsibility, resultCode, detailedResult,
    tier: secondOut ? "strong" : firstOut || choice.infieldRoute === "controlledNoThrow" ? "mixed" : "failure",
    decisionQuality: choice.advisable === "strong" ? "strong" : choice.advisable === "aggressive" ? "aggressive" : choice.advisable === "conservative" ? "conservative" : "reasonable",
    executionQuality: firstOut ? (isDoublePlay && !secondOut ? "partial" : "complete") : error ? "misplay" : choice.infieldRoute === "controlledNoThrow" ? "controlled" : "late",
    runnerSettlement, runnerSettlementIdentity: situation.runnerSettlementIdentity, outsCreated: runnerSettlement.outsCreated,
    runnerChanges: runnerSettlement.runnerChanges, runnersAfter: runnerSettlement.runnersAfter,
    scoringRunnerIds: runnerSettlement.scoringRunnerIds, runsAllowed: runnerSettlement.runsAllowed, error,
    primaryCause, secondaryCause: "", responsibleActor: primaryCause.startsWith("teammate") ? "teammate" : primaryCause === "timingWindow" ? "timingWindow" : "player",
    playerResponsibility: error ? "major" : "handled", teammateResponsibility: primaryCause.startsWith("teammate") ? "major" : isDoublePlay ? "shared" : "none",
    causeExplanation: primaryCause === "teammatePivot" ? "傳球的接球端未完成接球或轉傳；二壘手與游擊手的責任分開記錄。"
      : primaryCause === "teammateFirstBaseReceive" ? "傳球已進入一壘接球位置，但一壘手未完成接球；傳球與接球責任分開記錄。" : getSecondBaseCauseExplanation(primaryCause, ""),
    playerLeg: { reach: handoff.defensiveAccess.reachResolution.reached ? "completed" : "late",
      control: secureResolution.secured ? "completed" : "failed", transfer: thrown?.releaseQuality === "delayedRelease" ? "delayed" : controlled ? "completed" : "notReached",
      firstThrow: thrown?.throwAttempted ? thrown.throwQuality === "offline" ? "failed" : "completed" : "notAttempted" },
    teammateLeg: { receiver: receiverReady ? "completed" : "notReached", ...(isDoublePlay ? {
      secondBaseReceive: relay.receive ? "completed" : "notCompleted", secondBasePivot: relay.turn ? "completed" : "notCompleted",
      secondBaseSecondThrow: relay.turn ? "completed" : "notCompleted", firstBaseReceive: relay.firstBaseReceive ? "completed" : "notCompleted" } : {}) },
    firstLegState: { status: firstOut ? "completed" : "failed", targetBase: selection?.route.targetBase || null },
    continuationState: { status: secondOut ? "completed" : firstOut && isDoublePlay ? "windowClosed" : "settledByActorOutcomes", targetBase: isDoublePlay ? "first" : null, window: continuationWindow },
    timingResolution: { firstLeg: runnerThrowTiming, firstLegSettlement, relayToFirstWindow: continuationWindow },
    ballContext: situation.ballContext.type, ballDirection: situation.ballDirection, ballDepth: situation.ballDepth,
    batterSpeed: situation.batterSpeed, runnerSpeed: Math.max(...situation.runnerSpeeds.filter(Number.isFinite), 0),
    ...situation.playerCapabilities, firstStage: secureResolution.margin ?? handoff.defensiveAccess.reachResolution.margin,
    secondStage: thrown?.accuracyMargin ?? 0, returnTiming: 0, windows: situation.windows
  });
  return { sample, choice: { routeId: choice.routeId, matchDecision: choice.matchDecision }, secureResolution,
    decisionThrowState,
    runnerThrowTiming, resolution: attachHighSchoolInfieldActionFacts(match, situation, choice, resolution, sample) };
}

function ensureHighSchoolOrdinaryGroundBallInPlayHandoff(match, options = {}) {
  if (!match || typeof BattedBallGroundDefense === "undefined" || typeof OffensivePlateApproach === "undefined") return null;
  if (match.offensiveTacticalActionState?.selectedTacticalAction !== "standardAttack") return null;
  const playerPosition = match.developmentPositionOverride || getHighSchoolInfieldAssignmentPosition(match, player);
  const batter = getHighSchoolMatchSimulationEntity(match, match.currentBatter);
  const paIdentity = `${createHighSchoolOffensiveTacticalIdentity(match)}|ordinary-contact`;
  const existing = BattedBallGroundDefense.normalizeHandoff(match.groundBallInPlayState);
  const existingLineDrive = typeof BattedBallLineDriveDefense !== "undefined"
    ? BattedBallLineDriveDefense.normalizeCatchState(match.lineDriveCatchState) : null;
  const existingFlyBall = typeof BattedBallFlyBallDefense !== "undefined"
    ? BattedBallFlyBallDefense.normalizeFlyBallCatchState(match.flyBallCatchState) : null;
  if (existing?.identity === `${paIdentity}|ground-defense`) {
    if (existing.supported && !existing.settlementApplied) assertHighSchoolGroundParticipant(match);
    match.groundBallInPlayState = existing;
    return existing;
  }
  if (existingLineDrive?.identity === `${paIdentity}|line-drive-catch`) {
    if (existingLineDrive.supported && !existingLineDrive.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingLineDrive.physicalTruth, "2B", "player");
    match.lineDriveCatchState = existingLineDrive;
    return null;
  }
  if (existingFlyBall?.identity === `${paIdentity}|fly-ball-catch`) {
    if (existingFlyBall.supported && !existingFlyBall.settlementApplied) assertHighSchoolDetailedResponsibility(match, existingFlyBall.physicalTruth, existingFlyBall.defenderContext?.position, existingFlyBall.defenderContext?.defenderId);
    match.flyBallCatchState = existingFlyBall;
    return null;
  }
  const defender = {
    ...getDefensiveSimulationCapability(player, "內野手"),
    ...(options.situationOverrides?.playerCapabilities || {})
  };
  const physicalDefenderContext = physicalTruth => getHighSchoolPhysicalDefensePlayerContext(match, physicalTruth, {
    playerPosition, catching: defender.fielding, reaction: defender.reaction, range: defender.range
  }, options);
  const offense = getHighSchoolProvisionalOffensiveTacticalCapabilities(match);
  const initial = OffensivePlateApproach.createPlateAppearanceState({
    paIdentity,
    batterId: match.currentBatter,
    approach: "balancedAttack",
    context: { outs: match.outs, runners: match.runners.slice(), hasRunner: match.runners.some(Boolean) }
  });
  const fixture = options.ordinaryPlateAppearance || {};
  const pitch = fixture.pitch || { pitchLocationClass: "hitterPitch" };
  const pitchOptions = {
    recognitionRoll: fixture.recognitionRoll ?? 0,
    decisionRoll: fixture.decisionRoll ?? 0,
    contactRoll: fixture.contactRoll ?? 0,
    foulRoll: fixture.foulRoll ?? 1,
    physicalRolls: fixture.physicalRolls,
    outcomeRoll: fixture.outcomeRoll,
    physicalOutcomeResolver({ physicalTruth }) {
      const access = BattedBallGroundDefense.resolveGroundBallDefensiveAccess({
        physicalTruth,
        defenderContext: physicalDefenderContext(physicalTruth)
      });
      if (access.supported) return {
        result: "groundBallDefensePending",
        authority: "bbpB1PhysicalDefensePending",
        contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
        resolvedContact: null
      };
      if (typeof BattedBallLineDriveDefense !== "undefined") {
        const airborneContext = BattedBallLineDriveDefense.buildAirborneBallContext(physicalTruth);
        const catchAccess = airborneContext ? BattedBallLineDriveDefense.resolveCatchAccess({
          airborneContext,
          defenderContext: physicalDefenderContext(physicalTruth)
        }) : null;
        const catchWindow = catchAccess ? BattedBallLineDriveDefense.buildCatchTimingWindow({ airborneContext, defensiveAccess: catchAccess }) : null;
        if (catchAccess?.supported && catchWindow?.state !== "expired") return {
          result: "lineDriveCatchPending",
          authority: "bbpB2APhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      if (typeof BattedBallFlyBallDefense !== "undefined") {
        const flyBallDefender = getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options);
        const flyBallOpportunity = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
          identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: [], outs: match.outs,
          runnerEntities: [], defenderContext: flyBallDefender
        });
        if (flyBallOpportunity?.supported) return {
          result: "flyBallCatchPending",
          authority: "bbpB2B1PhysicalCatchPending",
          contactQuality: Number(physicalTruth.executionEvidence?.continuousContactScore) || 0,
          resolvedContact: null
        };
      }
      return null;
    }
  };
  const plateAppearanceState = OffensivePlateApproach.simulatePlateAppearance({
    state: initial,
    abilities: {
      observe: Number(offense.baseballIQ) || 5,
      baseballIQ: Number(offense.baseballIQ) || 5,
      ballSense: Number(offense.ballSense) || 5,
      batting: Number(offense.batting) || 5,
      power: Number(batter?.power) || Number(offense.batting) || 5,
      bats: batter?.bats || "R"
    },
    pitchSequence: [pitch],
    pitchOptions: [pitchOptions]
  });
  match.ordinaryDefensivePlateAppearanceState = JSON.parse(JSON.stringify(plateAppearanceState));
  const physicalTruth = plateAppearanceState.battedBallPhysicalTruth;
  const runnerEntities = match.runners.map((runnerId, index) => {
    if (!runnerId) return null;
    const entity = getHighSchoolMatchSimulationEntity(match, runnerId);
    return {
      runnerId,
      originBase: index + 1,
      speed: Number(entity?.speed) || 5,
      reaction: Number(entity?.reaction) || Number(entity?.defense) || 5,
      baseballIQ: Number(entity?.baseballIQ) || Number(entity?.decision) || 5
    };
  }).filter(Boolean);
  if (plateAppearanceState.result === "lineDriveCatchPending" && physicalTruth && typeof BattedBallLineDriveDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.flyBallCatchState = null;
    match.lineDriveCatchState = BattedBallLineDriveDefense.buildCatchOpportunity({
      identity: `${paIdentity}|line-drive-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: physicalDefenderContext(physicalTruth)
    });
    return null;
  }
  if (plateAppearanceState.result === "flyBallCatchPending" && physicalTruth && typeof BattedBallFlyBallDefense !== "undefined") {
    match.groundBallInPlayState = null;
    match.lineDriveCatchState = null;
    match.flyBallCatchState = BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
      identity: `${paIdentity}|fly-ball-catch`,
      physicalTruth,
      runners: match.runners,
      outs: match.outs,
      runnerEntities,
      preContactRunnerStates: options.preContactRunnerStates || {},
      defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
    });
    return null;
  }
  if (plateAppearanceState.result !== "groundBallDefensePending" || !physicalTruth) {
    const ordinaryInfield = isInfieldDecisionFamilyPosition(match.developmentPositionOverride || match.playerFieldingAssignment || match.position);
    match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
      version: BattedBallGroundDefense.VERSION,
      identity: `${paIdentity}|ground-defense`,
      sourceAuthority: "unsupportedOrdinaryContactLegacyFallback",
      physicalTruth: physicalTruth ? JSON.parse(JSON.stringify(physicalTruth)) : null,
      supported: false,
      ...(ordinaryInfield ? { fallbackAuthority: "existingOrdinaryPhysicalOutcome",
        defensiveOpportunity: physicalTruth ? getHighSchoolDefensiveOpportunity(match, physicalTruth) : null }
        : { fallbackAuthority: "existingSyntheticDefensiveContext" }),
      legacyFallbackResult: plateAppearanceState.result || ""
    });
    match.lineDriveCatchState = physicalTruth?.ballType === "lineDrive" && typeof BattedBallLineDriveDefense !== "undefined"
      ? BattedBallLineDriveDefense.buildCatchOpportunity({
        identity: `${paIdentity}|line-drive-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: physicalDefenderContext(physicalTruth)
      }) : null;
    match.flyBallCatchState = physicalTruth?.ballType === "flyBall" && typeof BattedBallFlyBallDefense !== "undefined"
      ? BattedBallFlyBallDefense.buildFlyBallCatchOpportunity({
        identity: `${paIdentity}|fly-ball-catch`, physicalTruth, runners: match.runners, outs: match.outs,
        runnerEntities, preContactRunnerStates: options.preContactRunnerStates || {},
        defenderContext: getHighSchoolFlyBallDefenderCatchContext(match, physicalTruth, options)
      }) : null;
    return match.groundBallInPlayState;
  }
  const forceState = BattedBallGroundDefense.deriveForceState({ runners: match.runners, outs: match.outs });
  match.lineDriveCatchState = null;
  match.flyBallCatchState = null;
  match.groundBallInPlayState = BattedBallGroundDefense.buildGroundBallDefensiveOpportunity({
    identity: `${paIdentity}|ground-defense`,
    physicalTruth,
    runners: match.runners,
    outs: match.outs,
    forceState,
    runnerEntities,
    batterRunner: { runnerId: match.currentBatter, speed: Number(batter?.speed) || 5 },
    preContactRunnerStates: options.preContactRunnerStates || {},
    defenderContext: physicalDefenderContext(physicalTruth)
  });
  const firstBaseContext = createHighSchoolFirstBaseContext(match, match.groundBallInPlayState, options);
  if (firstBaseContext) match.groundBallInPlayState = BattedBallGroundDefense.normalizeHandoff({
    ...match.groundBallInPlayState, defensiveOpportunity: getHighSchoolDefensiveOpportunity(match, physicalTruth), firstBaseContext });
  return match.groundBallInPlayState;
}

function resolveHighSchoolDefensivePlay(match, decision, randomSource = Math.random) {
  const pending = match?.activeSituation;
  if ((match?.groundBallInPlayState?.runnerThrowTiming || match?.groundBallInPlayState?.shortstopExecution) && pending?.lifecycleState === "resolved" && pending.resolution?.executionEvidence) {
    validateHighSchoolDecisionThrowState(match);
    const selected = pending.legalRoutes.find(route => route.matchDecision === decision || route.routeId === decision);
    if (!selected || (selected.routeId || selected.matchDecision) !== pending.decision?.selectedRoute) throw new Error("Stale defensive decision after execution");
    return pending.resolution.executionEvidence;
  }
  if (match?.positionDecisionFamily === "infield" && match.defensiveSituation?.familyId === "infield") {
    if (match.defensiveSituation.groundBallDefensiveContext?.supported) {
      assertHighSchoolGroundParticipant(match);
    }
    return infieldDecisionFamily.resolve(match.defensiveSituation, decision, match, randomSource);
  }
  if (match?.position === "捕手") return resolveHighSchoolCatcherDecision(match, decision, randomSource);
  return resolveLegacyHighSchoolDefensivePlay(match, decision, randomSource);
}

function resolveHighSchoolInfieldReceiver(situation, choice, sample, deliveryCompleted, match) {
  const position = choice.targetBase === "third" ? "3B" : choice.targetBase === "home" ? "C"
    : choice.targetBase === "second" || choice.targetBase === "secondThenFirst" ? "SS" : "1B";
  const legacy = position === "1B" ? situation.teammates?.firstBaseReceiver : position === "3B" ? situation.teammates?.thirdBaseReceiver
    : position === "C" ? situation.teammates?.catcher : situation.teammates?.shortstop;
  const actor = match?.rosters?.[match.defenseTeam] && typeof TeamRosterFoundation !== "undefined"
    ? TeamRosterFoundation.getCurrentDefender(match.rosters[match.defenseTeam], position) : null;
  const capabilities = actor ? getDefensiveSimulationCapability(actor, actor.position, match) : legacy?.capabilities || {};
  const fielding = Number(capabilities.fielding ?? 5), swing = (sample - .5) * 4;
  const available = Boolean((actor ? actor.id !== "player" : legacy) && legacy?.receivingAvailable !== false);
  const ready = available && fielding + swing >= 2.8;
  return Object.freeze({ receiverId: actor?.id || legacy?.id || null, receiverPosition: position, available, ready,
    secured: Boolean(deliveryCompleted && ready), status: !deliveryCompleted ? "notAttempted" : !available ? "unavailable" : ready ? "completed" : "failed",
    responsibleActor: deliveryCompleted && !ready ? "teammate" : "player",
    provenance: Object.freeze({ authority: actor ? "activeRosterReceiver+existingExecutionSample" : "declaredLegacyReceiver+existingExecutionSample",
      fielding, sample, swing, threshold: 2.8, consumedRng: false }) });
}

function createHighSchoolOffensiveTacticalIdentity(match) {
  return [
    match?.id || "match",
    match?.inning || 0,
    match?.half || "",
    match?.offenseTeam || "",
    match?.currentBatter || "",
    Number(match?.battingOrderIndex?.[match?.offenseTeam]) || 0,
    Number(match?.outs) || 0,
    (match?.runners || []).map(Boolean).join("")
  ].join("|");
}

function getHighSchoolControlledDecisionInput(match, state = match?.groundBallInPlayState) {
  if (typeof DefensiveDecisionThrowFoundation === "undefined" || state?.settlementApplied || !state?.secureResolution || !state.defensiveAccess?.reachResolution) return null;
  const routeWindows = {};
  for (const id of Object.keys(SECOND_BASE_ROUTE_DEFINITIONS)) {
    routeWindows[id] = getSecondBaseRouteWindow(id, match.defensiveSituation?.routeWindows || {}).state;
  }
  return { physicalTruth: state.physicalTruth, opportunity: getHighSchoolDefensiveOpportunity(match, state.physicalTruth),
    activeRoster: match.rosters[match.defenseTeam], capabilities: state.defensiveAccess.secureCapabilities,
    reachResult: state.defensiveAccess.reachResolution, secureResult: state.secureResolution,
    runners: match.runners, outs: match.outs, inning: match.inning, half: match.half, scores: match.scores,
    batterRunnerId: state.runnerRealization?.batterRunner?.runnerId, forceChain: state.forceChain,
    runnerStates: (state.runnerPhysicalStates || []).filter(r => match.runners.includes(r.runnerId)),
    runnerPhysicalStates: state.runnerPhysicalStates || [], routeWindows };
}

function attachHighSchoolInfieldActionFacts(match, situation, choice, resolution, sample) {
  if (situation.playerPosition === "三壘手" && situation.groundBallDefensiveContext?.supported)
    return attachHighSchoolThirdBaseActionFacts(match, situation, choice, resolution, sample);
  if (typeof DefensiveDecisionThrowFoundation === "undefined" || typeof TeamRosterFoundation === "undefined"
    || !match?.rosters?.[match.defenseTeam]) return resolution; // Isolated historical scenario harnesses.
  const roster = match.rosters[match.defenseTeam], playerPosition = TeamRosterFoundation.normalizePosition(situation.playerPosition);
  const coverage = resolution.playerRole === "coverPivot";
  const primaryPosition = coverage ? "SS" : playerPosition;
  const primary = TeamRosterFoundation.getCurrentDefender(roster, primaryPosition);
  const physicalIdentity = situation.groundBallDefensiveContext?.physicalTruth?.identity || null;
  const playIdentity = situation.runnerSettlementIdentity;
  const actions = [];
  const timing = resolution.timingResolution || {};
  const timingProvenance = { routeWindow: timing.routeWindow || timing.secondBaseForceWindow || null,
    timingClassification: timing.firstLeg?.timingClassification || null, timingMargin: timing.firstLeg?.timingMargin ?? null,
    relayToFirstWindow: timing.relayToFirstWindow || timing.relayToFirstWindowState || null, batterSpeed: situation.batterSpeed };
  const completed = value => ["completed", "recovered", "clean", "slightlyOffLine", "good"].includes(value);
  const status = (value, attempted = true) => completed(value) ? "completed" : !attempted ? "notAttempted" : "failed";
  function add(position, type, state, targetBase, receiverId, dependsOn = [], extra = {}) {
    const actor = TeamRosterFoundation.getCurrentDefender(roster, position);
    if (!actor) throw new Error("Invalid infield action actor");
    const capabilities = actor.id === "player" ? situation.playerCapabilities : getDefensiveSimulationCapability(actor, actor.position, match);
    const identity = `${playIdentity}|action|${actions.length + 1}`;
    actions.push({ actorId: actor.id, actorPosition: position, type, status: state, targetBase, receiverId,
      dependsOn, responsibleActor: actor.id === "player" ? "player" : "teammate",
      provenance: { authority: physicalIdentity ? "existingInfieldExecution+activeRoster" : "declaredLegacyInfieldExecution+activeRoster",
        sample, consumedRng: false, capabilities: { ...capabilities }, timing: timingProvenance,
        sourceStage: extra.sourceStage || type }, ...extra });
    return identity;
  }
  const control = coverage ? resolution.teammateLeg?.shortstopFielding : resolution.playerLeg?.control;
  const field = add(primaryPosition, "field", status(control), null, null, [], {
    sourceStage: coverage ? "shortstopFielding" : "control", errorCharged: resolution.error && !completed(control) });
  const routeId = resolution.activeRoute || resolution.routeId || choice.routeId;
  const dp = resolution.route === "doublePlay" && !resolution.reassessed;
  const target = dp || routeId === "forceSecond" ? "second" : routeId === "attackLeadRunnerThird" ? "third"
    : ["homeForceOut", "preventRunHome"].includes(routeId) ? "home" : "first";
  const receiverPosition = target === "second" ? (primaryPosition === "SS" ? "2B" : "SS")
    : target === "third" ? "3B" : target === "home" ? "C" : "1B";
  const receiver = TeamRosterFoundation.getCurrentDefender(roster, receiverPosition);
  const held = resolution.route === "controlledNoThrow" || routeId === "holdBall";
  const throwStage = coverage ? resolution.teammateLeg?.shortstopFirstThrow
    : resolution.reassessed ? resolution.playerLeg?.fallbackRelease : resolution.playerLeg?.firstThrow;
  const throwStatus = held ? "notAttempted" : status(throwStage, completed(control));
  const firstThrow = add(primaryPosition, "throw", throwStatus, target, receiver?.id, [field], {
    sourceStage: coverage ? "shortstopFirstThrow" : resolution.reassessed ? "fallbackRelease" : "firstThrow",
    errorCharged: resolution.error && completed(control) });
  const received = coverage ? resolution.playerLeg?.receive : dp
    ? (playerPosition === "SS" ? resolution.teammateLeg?.secondBaseReceive : resolution.teammateLeg?.shortstopReceive)
    : resolution.teammateLeg?.catcherReceive || resolution.teammateLeg?.receiver;
  const receiveStatus = throwStatus !== "completed" ? "notAttempted" : status(received);
  const receive = add(receiverPosition, "receive", receiveStatus, target, null, [firstThrow], { sourceStage: "receiver" });
  const retirements = resolution.runnerSettlement?.retirements || [];
  const firstRetirement = retirements.find(r => r.targetBase === target);
  const firstTargetRunner = firstRetirement?.runnerId || (target === "first" ? situation.batterId
    : target === "second" ? situation.runners[0] : target === "third" ? situation.runners[1] : situation.runners[2]);
  const tagged = routeId === "preventRunHome" || firstRetirement?.outType === "nonForceTag";
  const terminal = add(receiverPosition, tagged ? "tag" : "baseTouch",
    firstRetirement ? "completed" : receiveStatus === "completed" ? "late" : "notAttempted", target, null, [receive], {
      runnerId: firstTargetRunner, sourceStage: tagged ? "tagCompletion" : "retirementBaseTouch" });
  if (dp) {
    const pivotStage = coverage ? resolution.playerLeg?.pivot
      : playerPosition === "SS" ? resolution.teammateLeg?.secondBasePivot : resolution.teammateLeg?.shortstopPivot;
    const secondThrowStage = coverage ? resolution.playerLeg?.secondThrow
      : playerPosition === "SS" ? resolution.teammateLeg?.secondBaseSecondThrow : resolution.teammateLeg?.shortstopSecondThrow;
    const pivot = add(receiverPosition, "pivot", firstRetirement ? status(pivotStage) : "notAttempted", "first", null, [terminal]);
    const firstBase = TeamRosterFoundation.getCurrentDefender(roster, "1B");
    const secondThrow = add(receiverPosition, "throw", firstRetirement ? status(secondThrowStage, completed(pivotStage)) : "notAttempted",
      "first", firstBase?.id, [pivot], { sourceStage: "secondThrow" });
    const firstReceive = add("1B", "receive", completed(secondThrowStage) && firstRetirement
      ? status(resolution.teammateLeg?.firstBaseReceive) : "notAttempted", "first", null, [secondThrow], { sourceStage: "firstBaseReceive" });
    const secondRetirement = retirements.find(r => r.targetBase === "first");
    add("1B", "baseTouch", secondRetirement ? "completed" : "notAttempted", "first", null, [firstReceive], {
      runnerId: situation.batterId, sourceStage: "secondRetirementBaseTouch" });
  }
  const actionFacts = DefensiveDecisionThrowFoundation.createActionFacts({ playIdentity, physicalIdentity,
    sourceAuthority: physicalIdentity ? "physicalInfieldExecution" : "declaredLegacyInfieldScenario", actions });
  return Object.freeze({ ...resolution, executionSample: sample, actionFacts });
}

function getDefensiveSimulationCapability(subject = player, position = player.primaryPosition, matchContext = subject?.highSchoolMatch) {
  if (["simulation-roster", "team-roster-foundation"].includes(subject?.source)) {
    return Object.freeze({ fielding: subject.defense, reaction: subject.defense, range: subject.defense, arm: subject.arm, throwing: subject.arm, decision: Math.round((subject.defense + subject.contact) / 2) });
  }
  const rawSkills = subject.baseballSkills || {};
  const activeMatch = matchContext || (subject === player ? player.highSchoolMatch : null);
  const audit = getDevelopmentMatchPositionTestCapabilityAudit(subject, activeMatch);
  const skills = audit.active && !activeMatch?.completed
    ? Object.fromEntries(Object.keys(rawSkills).map(skill => [skill, audit.skills[skill]?.effective ?? rawSkills[skill]]))
    : rawSkills;
  const effectivePosition = audit.active ? audit.position : position;
  const positionTools = {
    "內野手": ["catching", "reaction", "throwing"],
    "外野手": ["catching", "range", "armStrength"],
    "捕手": ["blocking", "gameCalling", "throwing"],
    "投手": ["control", "reaction", "throwing"]
  }[position] || ["catching", "reaction", "throwing"];
  const values = positionTools.map(key => Number(skills[key]) || 0);
  const reactionSkill = Number(skills.reaction) || values[1] || 0;
  const throwingSkill = values[2] || 0;
  const armSkill = ["游擊手", "三壘手"].includes(effectivePosition) ? Number(skills.armStrength) || throwingSkill : throwingSkill;
  return Object.freeze({
    fielding: Math.round((values[0] * 2 + values[1] + (Number(subject.ballSense) || 0)) / 4),
    reaction: Math.round((reactionSkill * 2 + (Number(subject.ballSense) || 0)) / 3),
    range: Math.round(((Number(skills.range) || reactionSkill) * 2 + (Number(subject.fitness) || 0)) / 3),
    arm: Math.round((armSkill * 2 + (Number(subject.fitness) || 0)) / 3),
    throwing: Math.round((throwingSkill * 2 + (Number(subject.observe) || 0)) / 3),
    decision: Math.round(((Number(skills.baseballIQ) || 0) + (Number(subject.observe) || 0) + (Number(subject.discipline) || 0)) / 3)
  });
}

function nextHighSchoolMatchSimulationRandom(match) {
  const cursor = Math.max(0, Number(match.simulationCursor) || 0);
  const seed = (Math.max(1, Number(match.simulationSeed) || 1) + cursor * 73) % 997;
  match.simulationCursor = cursor + 1;
  return ((seed * 37 + 17) % 997) / 997;
}

function resolveBattedBallPhysicalTruth(input = {}) {
  const identity = String(input.identity || "ordinary-contact");
  const quality = resolveContactQuality({ ...input, identity });
  const ballType = resolveBattedBallType({ ...input, identity, contactQuality: quality.contactQuality });
  const pace = resolveBattedBallPace({ ...input, identity, contactQuality: quality.contactQuality, ballType });
  const direction = resolveBattedBallDirection({ ...input, identity });
  const depth = resolveBattedBallDepth({ ...input, identity, contactQuality: quality.contactQuality, ballType });
  return deepFreeze({
    version: VERSION,
    identity,
    contactQuality: quality.contactQuality,
    ballType,
    pace: pace.pace,
    direction: direction.direction,
    depth: depth.depth,
    executionEvidence: {
      actualPitch: clone(input.actualPitch || {}),
      recognition: clone(input.recognition || {}),
