      depthRollConsumed: depth.consumed
    }
  });
}

function buildGroundBallDefensiveOpportunity(input = {}) {
  const physicalTruth = input.physicalTruth || {};
  const forceChain = input.forceChain || (ForceAdvancement ? ForceAdvancement.buildInitialLiveBallForceChain({
    runners: input.runners,
    batterRunnerId: input.batterRunner?.runnerId || "batter-runner"
  }) : null);
  const forceState = forceChain && ForceAdvancement
    ? ForceAdvancement.deriveCompatibilityForceState(forceChain, { outs: input.outs })
    : input.forceState || deriveForceState({ runners: input.runners, outs: input.outs });
  const defensiveAccess = resolveGroundBallDefensiveAccess(input);
  const ballContext = projectGroundBallCompatibilityContext(physicalTruth, defensiveAccess);
  const runnerRealization = buildGroundBallRunnerRealization({ ...input, forceChain, forceState, defensiveAccess, ballContext });
  if (!runnerRealization) return null;
  const timingWindows = buildGroundBallTimingWindows({ ballContext, runnerRealization });
  const homeRunner = runnerRealization.existingRunners.find(state => state.originBase === 3
    && state.targetBase === "home" && ["advancing", "committed"].includes(state.movementState));
  const choices = defensiveAccess.supported ? ["secureFirstBaseOut"] : [];
  const thirdBase = defensiveAccess.playerPosition === "三壘手";
  if (defensiveAccess.supported && forceState.forceAtSecond) {
    if (defensiveAccess.playerPosition === "游擊手") choices.push("forceSecond");
    if (Number(input.outs) < 2) choices.push(thirdBase ? "initiate543"
      : defensiveAccess.playerPosition === "游擊手" ? "startDoublePlaySecond" : "initiate463");
  }
  if (defensiveAccess.supported && thirdBase && forceState.forceAtThird) choices.push("stepThird");
  if (!thirdBase && defensiveAccess.supported && forceState.forceAtHome && timingWindows.homeOutWindow.state !== "expired") choices.push("homeForceOut");
  else if (!thirdBase && defensiveAccess.supported && homeRunner && timingWindows.homeOutWindow.state !== "expired") choices.push("preventRunHome");
  return deepFreeze({
    version: VERSION,
    identity: String(input.identity || "ordinary-ground-ball"),
    sourceAuthority: "BattedBallPhysicalTruth",
    physicalTruth: clone(physicalTruth),
    ...(Opportunity && [Opportunity.GROUND_TOPOLOGY_VERSION, Opportunity.FIRST_BASE_GROUND_TOPOLOGY_VERSION].includes(input.defenderContext?.defensiveOpportunity?.topologyVersion)
      ? { defensiveOpportunity: clone(input.defenderContext.defensiveOpportunity) } : {}),
    forceChain,
    forceState,
    runnerRealization,
    runnerPhysicalStates: runnerRealization.runnerPhysicalStates,
    defensiveAccess,
    ballContext,
    timingWindows,
    availableDecisionIds: choices,
    firstLegState: { status: "pending", targetBase: forceState.forceAtSecond ? "second" : "first" },
    continuationState: { status: "pendingReassessment", window: timingWindows.relayToFirstWindow.state, targetBase: "first" },
    supported: defensiveAccess.supported,
    settlementApplied: false
  });
}

function buildGroundBallRunnerRealization(input = {}) {
  const truth = input.physicalTruth || {};
  if (truth.ballType !== "groundBall") return null;
  const forceChain = input.forceChain || (ForceAdvancement ? ForceAdvancement.buildInitialLiveBallForceChain({
    runners: input.runners,
    batterRunnerId: input.batterRunner?.runnerId || "batter-runner"
  }) : null);
  const forceState = forceChain && ForceAdvancement
    ? ForceAdvancement.deriveCompatibilityForceState(forceChain, { outs: input.outs })
    : input.forceState || deriveForceState({ runners: input.runners, outs: input.outs });
  const entities = Array.isArray(input.runnerEntities) ? input.runnerEntities : [];
  const preContact = input.preContactRunnerStates || {};
  const existingRunners = entities.filter(runner => runner?.runnerId).map(runner => {
    const originBase = Number(runner.originBase);
    const forcedMovement = forceChain && ForceAdvancement ? ForceAdvancement.getForcedMovement(forceChain, runner.runnerId) : null;
    const forced = forcedMovement ? true : originBase === 1 ? forceState.forceAtSecond
      : originBase === 2 ? forceState.forceAtThird : originBase === 3 ? forceState.forceAtHome : false;
    const observed = preContact[runner.runnerId] || {};
    const nextTarget = ["", "second", "third", "home"][originBase] || "";
    const hasObservedDecision = ["commitAdvance", "holdBase"].includes(observed.movementDecision);
    const opportunity = originBase === 3 && !forced ? buildRunner3BAdvanceOpportunity({
      physicalTruth: truth,
      runner,
      defensiveAccess: input.defensiveAccess,
      playerPosition: input.defenderContext?.playerPosition,
      outs: input.outs,
      isForced: false
    }) : null;
    const advanceDecision = opportunity ? resolveRunner3BAdvanceDecision(opportunity, runner, { identity: input.identity }) : null;
    const observedAdvance = observed.movementDecision === "commitAdvance"
      && (!observed.targetBase || observed.targetBase === nextTarget);
    const movementDecision = forced ? "commitAdvance"
      : hasObservedDecision ? (observedAdvance ? "commitAdvance" : "holdBase")
        : advanceDecision?.decision || "holdBase";
    const naturalStartQuality = Number(runner.reaction) >= 8 ? "preparedStart"
      : Number(runner.reaction) <= 3 ? "lateStart" : "normalStart";
    const state = createRunnerState({
      runnerId: runner.runnerId,
      originBase,
      targetBase: forcedMovement?.targetBase || (movementDecision === "commitAdvance" ? nextTarget : ["", "first", "second", "third"][originBase]),
      movementDecision,
      startQuality: observed.startQuality || naturalStartQuality,
      speed: runner.speed
    });
    return deepFreeze({
      ...state,
      movementState: observed.movementState === "committed" && movementDecision === "commitAdvance" ? "committed" : state.movementState,
      advancementProgress: ["early", "midway", "late"].includes(observed.advancementProgress) ? observed.advancementProgress
        : movementDecision === "commitAdvance" && Number(runner.speed) >= 8 ? "midway" : "early",
      isForced: forced,
      forcedMovementTarget: forcedMovement?.targetBase || (forced ? state.targetBase : null),
      forceReason: forcedMovement?.forceReason || "",
      chainDepth: forcedMovement?.chainDepth ?? null,
      advanceOpportunity: opportunity,
      advanceDecision: opportunity ? (hasObservedDecision ? {
        ...clone(advanceDecision),
        authority: "explicitPreContactRunnerState",
        decision: movementDecision,
        decisionBasis: "explicitPreContactRunnerState"
      } : advanceDecision) : null
    });
  });
  const batterState = createRunnerState({
    runnerId: input.batterRunner?.runnerId || "batter-runner",
    originBase: "batter",
    targetBase: "first",
    movementDecision: "commitAdvance",
    startQuality: input.batterRunner?.startQuality || "normalStart",
    speed: input.batterRunner?.speed
  });
  const batterRunner = deepFreeze({
    ...batterState,
    isForced: true,
    forcedMovementTarget: "first",
    forceReason: forceChain?.batterRunner?.forceReason || "batterRunnerRequiredToFirst",
    chainDepth: 0
  });
  return deepFreeze({
    version: "ground-ball-runner-realization-v1",
    authority: "bbpPhysicalTruth+baseForceState",
    forceChain,
    forceState,
    existingRunners,
    batterRunner,
    runnerAdvanceOpportunities: existingRunners.map(state => state.advanceOpportunity).filter(Boolean),
    runnerAdvanceDecisions: existingRunners.map(state => state.advanceDecision).filter(Boolean),
    runnerPhysicalStates: [...existingRunners, batterRunner]
  });
}

function resolveThrow({ input, opportunity, selection, capabilities, rolls, transferState } = {}) {
  validateSelection(selection, opportunity, input);
  const base = throwBase(selection);
  if (selection.route.action === "baseTouch") fail("base touch cannot resolve a throw");
  if (selection.route.action === "holdBall") return freeze({ ...base, throwAttempted: false, throwQuality: "notAttempted",
    releaseQuality: "held", ballArrivalState: "controlledByThrower", variationEvidence: { consumed: false }, authority: "deliberateHold" });
  if (!["ready", "completed", "delayed", "failed"].includes(transferState)) fail("unknown transfer readiness");
  if (transferState === "failed") return freeze({ ...base, throwAttempted: false, throwQuality: "notAttempted",
    releaseQuality: "transferUnavailable", ballArrivalState: "releaseUnavailable", variationEvidence: { consumed: false }, authority: "upstreamTransfer" });
  if (capabilities?.defenderId !== selection.defenderId || !Number.isFinite(capabilities.arm) || !Number.isFinite(capabilities.throwing)) fail("throw capability adapter mismatch");
  const demand = throwDemand(selection, input.secureResult);
  const sample = stage => { const explicit = rolls?.[stage]; const namespace = RNG_NAMESPACES[stage];
    const roll = Number.isFinite(explicit) ? Math.max(0, Math.min(1, explicit)) : Physical.deterministicUnit(namespace, base.identity, stage);
    return { namespace, roll, adjustment: (0.5 - roll) * 2 }; };
  const strengthVariation = sample("strength"), accuracyVariation = sample("accuracy");
  const arm = Math.max(0, Math.min(20, capabilities.arm)), throwing = Math.max(0, Math.min(20, capabilities.throwing));
  const strengthMargin = arm - demand.strength + strengthVariation.adjustment;
  const accuracyMargin = throwing - demand.accuracy + accuracyVariation.adjustment;
  const quality = accuracyMargin < -1 ? "offline" : strengthMargin < 0 ? "lateWeakThrow" : accuracyMargin < 1 ? "challengingReceive" : "onTarget";
  return freeze({ ...base, throwAttempted: true, throwDemand: demand, strengthMargin, accuracyMargin,
    throwQuality: quality, releaseQuality: transferState === "delayed" ? "delayedRelease" : "readyRelease",
    ballArrivalState: { offline: "outsideReceiverReach", lateWeakThrow: "insufficientDelivery", challengingReceive: "receiverChallenged", onTarget: "atReceiverTarget" }[quality],
    inputs: { arm, throwing, transferState, secureQuality: input.secureResult.secureQuality },
    variationEvidence: { consumed: true, strength: strengthVariation, accuracy: accuracyVariation }, authority: "throwCapabilities+coarseDemand+separateVariation" });
}

function throwDemand(selection, secure) {
  const position = selection.position, target = selection.route.targetBase;
  const distanceClass = ["LF", "CF", "RF"].includes(position) || (position === "3B" && target === "first") ? "long"
    : (["1B", "2B", "SS"].includes(position) && target === "second") || (position === "3B" && target === "home") ? "short" : "medium";
  const arrivalPressure = secure.inputs?.arrivalQuality === "stretchedArrival" ? 1 : 0;
  const controlPressure = secure.secureQuality === "bobbleButControlled" ? 1 : 0;
  return { distanceClass, strength: { short: 3, medium: 5, long: 7 }[distanceClass] + arrivalPressure,
    accuracy: { short: 3, medium: 4, long: 5 }[distanceClass] + arrivalPressure + controlPressure,
    arrivalPressure, controlPressure, units: "coarseRelativeDemand" };
}

function resolveTiming(args){
  const {input,opportunity,selection,throwResolution:thrown,runnerState,receiverState}=args;
  Decision.validateSelection(selection,opportunity,input);
  if(!thrown||thrown.identity!==`${selection.identity}|throw-v1`||thrown.decisionIdentity!==selection.identity
    ||thrown.throwerId!==selection.defenderId||thrown.throwerPosition!==selection.position
    ||["routeId","targetRunnerId","targetBase","receiverId","receiverPosition"].some(key=>thrown[key]!==selection.route[key]))fail("stale throw / receiver / target");
  const base={version:VERSION,identity:`${thrown.identity}|timing-v1`,decisionIdentity:selection.identity,throwIdentity:thrown.identity,
    targetRunnerId:thrown.targetRunnerId,targetBase:thrown.targetBase,receiverId:thrown.receiverId,
    authority:"resolvedThrow+existingRunnerPhysicalState+receiverReadiness",variationEvidence:{consumed:false}};
  if(selection.route.action==="holdBall"){
    if(thrown.throwAttempted!==false)fail("hold includes throw");
    return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
      runnerArrival:null,ballArrival:null,receiverCompletion:null,reason:"heldBall"});
  }
  const current=(input.runnerPhysicalStates||[]).find(r=>r.runnerId===thrown.targetRunnerId);
  if(!current||!same(current,runnerState)||current.targetBase!==thrown.targetBase
    ||(current.originBase==="batter"?input.batterRunnerId!==current.runnerId:input.runners[Number(current.originBase)-1]!==current.runnerId))fail("stale runner physical state");
  const forced=Force.getForcedMovement(opportunity.context.forceChain,current.runnerId);
  if(!forced&&!Decision.isAdvancingTo(current,thrown.targetBase))fail("runner not in contest");
  if(!receiverState||receiverState.receiverId!==thrown.receiverId||!same(receiverState,input.receiverState))fail("stale receiver completion");
  const runnerArrival=deriveRunnerArrival(current);
  const noContest=!thrown.throwAttempted||thrown.throwQuality==="offline"||receiverState.ready!==true;
  const receiveDelay=Number(receiverState.receiveDelay??0),tagDelay=Number(receiverState.tagDelay??1);
  if(!Number.isFinite(receiveDelay)||receiveDelay<0||!Number.isFinite(tagDelay)||tagDelay<0)fail("invalid receiver delay");
  if(noContest)return freeze({...base,contestAvailable:false,timingClassification:"noContest",timingMargin:null,
    runnerArrival,ballArrival:{quality:thrown.throwQuality},receiverCompletion:{...clone(receiverState),status:"unavailableReceive"},reason:"unusableThrowOrReceiver"});
  const qualityDelay={onTarget:0,challengingReceive:1,lateWeakThrow:3}[thrown.throwQuality];
  if(qualityDelay===undefined)fail("generic timing cannot reinterpret legacy composite throw");
  const distanceDelay={short:0,medium:1,long:2}[thrown.throwDemand?.distanceClass];
  if(distanceDelay===undefined)fail("missing throw distance");
  const ballTime=4+distanceDelay+qualityDelay+(thrown.releaseQuality==="delayedRelease"?1:0);
  const completionTime=ballTime+receiveDelay;
  const margin=Math.round((runnerArrival.relativeArrival-completionTime)*1000)/1000;
  return freeze({...base,contestAvailable:true,timingClassification:classify(margin),timingMargin:margin,runnerArrival,
    ballArrival:{relativeArrival:ballTime,quality:thrown.throwQuality,releaseQuality:thrown.releaseQuality,distanceClass:thrown.throwDemand.distanceClass},
    receiverCompletion:{...clone(receiverState),status:thrown.throwQuality==="challengingReceive"?"challengedReceive":"readyReceive",
      relativeCompletion:completionTime,tagCompletion:completionTime+tagDelay},reason:"physicalArrivalComparison"});
}

function deriveRunnerArrival(current){
  if(!current||!Number.isFinite(current.speed)||!["preparedStart","normalStart","lateStart","brokenStart"].includes(current.startQuality))fail("missing runner arrival inputs");
  const start={preparedStart:-1,normalStart:0,lateStart:1,brokenStart:2}[current.startQuality];
  const progress={early:0,midway:1.5,late:3,nearArrival:4}[current.advancementProgress||"early"];
  if(progress===undefined)fail("unknown runner progress");
  return freeze({...clone(current),profile:Runner.deriveArrivalProfile(current.speed,current.startQuality),
    relativeArrival:10-Math.max(0,Math.min(20,current.speed))*0.45+start-progress});
}

function resolveFairContactBallInPlay(state, pitch, abilities, recognition, options = {}) {
  const identity = `${state.paIdentity}|pitch-${state.pitchNumber + 1}`;
  const swingIntent = options.swingIntent || state.swingIntent;
  const physicalTruth = BattedBallPhysical ? BattedBallPhysical.resolveBattedBallPhysicalTruth({
    identity,
    actualPitch: pitch,
    recognition,
    action: "swing",
    contact: true,
    swingIntent,
    bats: abilities.bats || "R",
    abilities: { batting: abilities.batting, power: abilities.power },
    rolls: options.physicalRolls
  }) : null;
  const physicalOutcome = physicalTruth && typeof options.physicalOutcomeResolver === "function"
    ? options.physicalOutcomeResolver({ physicalTruth, state, pitch, abilities, recognition }) : null;
  let outcome;
  if (physicalOutcome?.result && /Pending$/.test(physicalOutcome.result)) {
    outcome = deepFreeze({ ...clone(physicalOutcome), adapterAuthority: physicalOutcome.authority || "physicalOutcomeResolver" });
  } else if (physicalTruth) {
    if (!OutcomeMapping) throw new Error("Physical BIP requires BattedBallOutcomeMapping");
    const official = OutcomeMapping.resolveOfficialBallInPlayOutcome({
      physicalTruth,
      defenseOutcome: physicalOutcome?.result ? { ...physicalOutcome, authority: physicalOutcome.authority || "physicalOutcomeResolver", settled: true, physicalIdentity: physicalTruth.identity } : physicalOutcome,
      rolls: { ...options.mappingRolls, ...(options.outcomeRoll !== undefined && options.mappingRolls?.hit === undefined ? { hit: options.outcomeRoll } : {}) }
    });
    outcome = deepFreeze({ ...official, adapterAuthority: official.authority,
      contactQuality: physicalTruth.executionEvidence.continuousContactScore, resolvedContact: official.trace.hitScore });
  } else outcome = resolveLegacyBallInPlayOutcome({ ...state, swingIntent }, pitch, abilities, recognition, null, options.outcomeRoll);
  return deepFreeze({ physicalTruth, outcome });
}

function buildInfieldTeammateContext(match, playerPosition) {
  if (typeof TeamRosterFoundation !== "undefined") TeamRosterFoundation.assertActiveDefense(match?.rosters?.[getHighSchoolPlayerTeamSide(match)]);
  const pivotPosition = playerPosition === "二壘手" ? "游擊手" : playerPosition === "一壘手" ? "游擊手" : "二壘手";
  const firstBasePosition = playerPosition === "一壘手" ? "投手" : "一壘手";
  const pivot = getInfieldTeammateForPosition(match, pivotPosition);
  const firstBase = getInfieldTeammateForPosition(match, firstBasePosition);
  const adapt = (entity, fallbackPosition) => {
    const capability = entity ? getDefensiveSimulationCapability(entity, entity.position) : {};
    return Object.freeze({
      id: entity?.id || "",
      name: entity?.name || fallbackPosition,
      position: entity?.position || fallbackPosition,
      receivingAvailable: Boolean(entity),
      capabilities: Object.freeze({ ...capability })
    });
  };
  return Object.freeze({
    receivingFielder: adapt(pivot, pivotPosition),
    pivotFielder: adapt(pivot, pivotPosition),
    firstBaseReceiver: adapt(firstBase, firstBasePosition),
    shortstop: adapt(getInfieldTeammateForPosition(match, "游擊手"), "游擊手"),
    secondBaseman: adapt(getInfieldTeammateForPosition(match, "二壘手"), "二壘手"),
    thirdBaseReceiver: adapt(getInfieldTeammateForPosition(match, "三壘手"), "三壘手"),
    catcher: adapt(getInfieldTeammateForPosition(match, "捕手"), "捕手")
  });
}

function resolveRoutineDefensivePlay(match, situation = match?.defensiveSituation, randomSource = null, options = {}) {
  if (!match || situation?.familyId !== "infield") return null;
  if (situation.groundBallDefensiveContext?.supported) {
    assertHighSchoolGroundParticipant(match);
  }
  const legalChoices = infieldDecisionFamily.generateLegalChoices(situation, match);
  const classification = classifyPositionFamilyPlay(situation, legalChoices, true);
  if (classification.eventClassification !== "playerRoutinePlay" && options.densitySuppressed !== true) return null;
  const source = randomSource === null ? () => nextHighSchoolMatchSimulationRandom(match) : randomSource;
  const routineChoice = situation.groundBallDefensiveContext?.firstBaseContext && legalChoices[0]?.routeId === "pitcherCoverFirst"
    ? legalChoices[0] : legalChoices.find(choice => choice.routeId === "coverSecondFor643") || legalChoices.find(choice => choice.matchDecision === "secure") || legalChoices[0];
  const resolution = routineChoice ? infieldDecisionFamily.resolve(situation, routineChoice.matchDecision, match, source) : null;
  if (!resolution) return null;
  return Object.freeze({
    ...resolution,
    // Density suppression already admitted this execution as a routine play.
    // Reusing the candidate's meaningful label would make routine settlement reject it.
    eventClassification: "playerRoutinePlay",
    decisionTension: classification.decisionTension,
    executionRoute: resolution.firstBaseEvidence ? routineChoice.route : getInfieldRoutineExecutionRoute(situation)
  });
}

function getCurrentDefender(roster, position) {
  if (!validateActiveDefense(roster).ok) return null;
  const code = normalizePosition(position);
  return roster.lineup.find(actor => normalizePosition(actor.defensivePosition || actor.position) === code) || null;
}
